-- The second lock (docs/town/prd/foundation-workspaces-accounts.md, slice 4): row-level security on every workspace
-- table, so a query that forgets its "workspace_id = $w" still can't reach another workspace's rows. The studio's
-- queries on these tables run as the role creavia_workspace, inside a transaction that first names the workspace
-- (lib/db.ts: set_config('app.workspace', …) and SET LOCAL ROLE): that role sees and writes only rows of the named
-- workspace, and nothing when none is named. Every other role keeps what it had: the owner (migrations, the nightly
-- backup) isn't subject to row security, and a policy for any other role (Neon Realtime's, if it differs) lets it
-- read as before. Without the right to make roles, this file changes nothing and the lock stays off (lib/db.ts says
-- so). Safe to run again; one statement per line, so gen-schema keeps each DO block whole.
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'creavia_workspace') THEN CREATE ROLE creavia_workspace NOLOGIN; END IF; EXCEPTION WHEN insufficient_privilege OR duplicate_object OR unique_violation THEN NULL; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'creavia_workspace') AND NOT pg_has_role(current_user, 'creavia_workspace', 'MEMBER') THEN EXECUTE format('GRANT creavia_workspace TO %I', current_user); END IF; EXCEPTION WHEN insufficient_privilege OR unique_violation THEN NULL; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'creavia_workspace') THEN EXECUTE format('GRANT USAGE ON SCHEMA %I TO creavia_workspace', current_schema()); EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA %I TO creavia_workspace', current_schema()); EXECUTE format('GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA %I TO creavia_workspace', current_schema()); EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO creavia_workspace', current_schema()); EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO creavia_workspace', current_schema()); END IF; EXCEPTION WHEN insufficient_privilege OR unique_violation THEN NULL; END $$;
ALTER TABLE posts ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'creavia_workspace') AND NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = current_schema() AND tablename = 'posts' AND policyname = 'workspace_only') THEN CREATE POLICY workspace_only ON posts TO creavia_workspace USING (workspace_id = current_setting('app.workspace', true)) WITH CHECK (workspace_id = current_setting('app.workspace', true)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = current_schema() AND tablename = 'posts' AND policyname = 'other_roles') THEN CREATE POLICY other_roles ON posts USING (current_user <> 'creavia_workspace') WITH CHECK (current_user <> 'creavia_workspace'); END IF; END $$;
